--
-- OpenCart.com Platform Database Schema & Official Seed Data
--

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+00:00";

-- --------------------------------------------------------
-- Table structure for `oc_api`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_api`;
CREATE TABLE `oc_api` (
  `api_id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(64) NOT NULL,
  `key` text NOT NULL,
  `status` tinyint(1) NOT NULL,
  `date_added` datetime NOT NULL,
  `date_modified` datetime NOT NULL,
  PRIMARY KEY (`api_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_api_ip`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_api_ip`;
CREATE TABLE `oc_api_ip` (
  `api_ip_id` int NOT NULL AUTO_INCREMENT,
  `api_id` int NOT NULL,
  `ip` varchar(40) NOT NULL,
  PRIMARY KEY (`api_ip_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_api_session`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_api_session`;
CREATE TABLE `oc_api_session` (
  `api_session_id` int NOT NULL AUTO_INCREMENT,
  `api_id` int NOT NULL,
  `session_id` varchar(32) NOT NULL,
  `ip` varchar(40) NOT NULL,
  `date_added` datetime NOT NULL,
  `date_modified` datetime NOT NULL,
  PRIMARY KEY (`api_session_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_banner`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_banner`;
CREATE TABLE `oc_banner` (
  `banner_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL,
  `status` tinyint(1) NOT NULL,
  PRIMARY KEY (`banner_id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_banner_image`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_banner_image`;
CREATE TABLE `oc_banner_image` (
  `banner_image_id` int NOT NULL AUTO_INCREMENT,
  `banner_id` int NOT NULL,
  `language_id` int NOT NULL,
  `title` varchar(64) NOT NULL,
  `link` varchar(255) NOT NULL,
  `image` varchar(255) NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`banner_image_id`)
) ENGINE=MyISAM AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_blog`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_blog`;
CREATE TABLE `oc_blog` (
  `blog_id` int NOT NULL AUTO_INCREMENT,
  `blog_category_id` int NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` mediumtext NOT NULL,
  `author` varchar(64) NOT NULL,
  `image` varchar(255) NOT NULL DEFAULT '',
  `image_status` tinyint(1) NOT NULL DEFAULT '1',
  `trending` tinyint(1) NOT NULL DEFAULT '0',
  `viewed` int NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `date_added` datetime NOT NULL,
  `date_modified` datetime NOT NULL,
  PRIMARY KEY (`blog_id`),
  KEY `blog_category_id` (`blog_category_id`)
) ENGINE=MyISAM AUTO_INCREMENT=311 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_blog_category`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_blog_category`;
CREATE TABLE `oc_blog_category` (
  `blog_category_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`blog_category_id`)
) ENGINE=MyISAM AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_blog_comment`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_blog_comment`;
CREATE TABLE `oc_blog_comment` (
  `blog_comment_id` int NOT NULL AUTO_INCREMENT,
  `blog_id` int NOT NULL,
  `parent_id` int NOT NULL DEFAULT '0',
  `member_id` int NOT NULL,
  `comment` text NOT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`blog_comment_id`),
  KEY `blog_id` (`blog_id`),
  KEY `parent_id` (`parent_id`)
) ENGINE=MyISAM AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_country`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_country`;
CREATE TABLE `oc_country` (
  `country_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(128) NOT NULL,
  `iso_code_2` varchar(2) NOT NULL,
  `iso_code_3` varchar(3) NOT NULL,
  `address_format` text NOT NULL,
  `postcode_required` tinyint(1) NOT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`country_id`)
) ENGINE=MyISAM AUTO_INCREMENT=258 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_currency`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_currency`;
CREATE TABLE `oc_currency` (
  `currency_id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(32) NOT NULL,
  `code` varchar(3) NOT NULL,
  `symbol_left` varchar(12) NOT NULL,
  `symbol_right` varchar(12) NOT NULL,
  `decimal_place` char(1) NOT NULL,
  `value` double(15,8) NOT NULL,
  `status` tinyint(1) NOT NULL,
  `date_modified` datetime NOT NULL,
  PRIMARY KEY (`currency_id`)
) ENGINE=MyISAM AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_download`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_download`;
CREATE TABLE `oc_download` (
  `download_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL,
  `description` mediumtext NOT NULL,
  `filename` varchar(160) NOT NULL,
  `mask` varchar(128) NOT NULL,
  `href` varchar(255) NOT NULL,
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`download_id`)
) ENGINE=MyISAM AUTO_INCREMENT=83 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_event`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_event`;
CREATE TABLE `oc_event` (
  `event_id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(64) NOT NULL,
  `trigger` text NOT NULL,
  `action` text NOT NULL,
  `status` tinyint(1) NOT NULL,
  `sort_order` int NOT NULL,
  PRIMARY KEY (`event_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_extension`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_extension`;
CREATE TABLE `oc_extension` (
  `extension_id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL,
  `extension_category_id` int NOT NULL,
  `name` varchar(128) NOT NULL,
  `description` mediumtext NOT NULL,
  `documentation` mediumtext NOT NULL,
  `history` text NOT NULL,
  `license` tinyint(1) NOT NULL DEFAULT '0',
  `license_period` int NOT NULL DEFAULT '12',
  `price` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `image` varchar(255) NOT NULL DEFAULT '',
  `banner` varchar(255) NOT NULL DEFAULT '',
  `tag` text NOT NULL,
  `cloud` varchar(255) NOT NULL DEFAULT '',
  `recommended` tinyint(1) NOT NULL DEFAULT '0',
  `featured` tinyint(1) NOT NULL DEFAULT '0',
  `publish` tinyint(1) NOT NULL DEFAULT '1',
  `notify` tinyint(1) NOT NULL DEFAULT '1',
  `alert` tinyint(1) NOT NULL DEFAULT '1',
  `sales` int NOT NULL DEFAULT '0',
  `downloaded` int NOT NULL DEFAULT '0',
  `rating` int NOT NULL DEFAULT '5',
  `rating_total` int NOT NULL DEFAULT '0',
  `reviews_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `comments_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `date_added` datetime NOT NULL,
  `date_modified` datetime NOT NULL,
  PRIMARY KEY (`extension_id`),
  KEY `extension_category_id` (`extension_category_id`),
  KEY `member_id` (`member_id`)
) ENGINE=MyISAM AUTO_INCREMENT=49867 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_extension_category`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_extension_category`;
CREATE TABLE `oc_extension_category` (
  `extension_category_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`extension_category_id`)
) ENGINE=MyISAM AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_extension_comment`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_extension_comment`;
CREATE TABLE `oc_extension_comment` (
  `extension_comment_id` int NOT NULL AUTO_INCREMENT,
  `extension_id` int NOT NULL,
  `parent_id` int NOT NULL DEFAULT '0',
  `member_id` int NOT NULL,
  `comment` text NOT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`extension_comment_id`),
  KEY `extension_id` (`extension_id`),
  KEY `parent_id` (`parent_id`)
) ENGINE=MyISAM AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_extension_download`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_extension_download`;
CREATE TABLE `oc_extension_download` (
  `extension_download_id` int NOT NULL AUTO_INCREMENT,
  `extension_id` int NOT NULL,
  `name` varchar(128) NOT NULL,
  `filename` varchar(160) NOT NULL,
  `mask` varchar(128) NOT NULL,
  `cloud` tinyint(1) NOT NULL DEFAULT '1',
  `approved` tinyint(1) NOT NULL DEFAULT '1',
  `downloaded` int NOT NULL DEFAULT '0',
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`extension_download_id`),
  KEY `extension_id` (`extension_id`)
) ENGINE=MyISAM AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_extension_download_path`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_extension_download_path`;
CREATE TABLE `oc_extension_download_path` (
  `extension_download_id` int NOT NULL,
  `download_id` int NOT NULL,
  PRIMARY KEY (`extension_download_id`,`download_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_extension_image`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_extension_image`;
CREATE TABLE `oc_extension_image` (
  `extension_image_id` int NOT NULL AUTO_INCREMENT,
  `extension_id` int NOT NULL,
  `image` varchar(255) NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`extension_image_id`),
  KEY `extension_id` (`extension_id`)
) ENGINE=MyISAM AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_extension_promotion`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_extension_promotion`;
CREATE TABLE `oc_extension_promotion` (
  `promotion_id` int NOT NULL AUTO_INCREMENT,
  `extension_id` int NOT NULL,
  `member_id` int NOT NULL,
  `days` int NOT NULL DEFAULT '30',
  `total` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `payment_method` varchar(64) NOT NULL DEFAULT 'PayPal',
  `transaction_id` varchar(128) NOT NULL DEFAULT '',
  `order_status_id` int NOT NULL DEFAULT '5',
  `date_start` date NOT NULL,
  `date_end` date NOT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`promotion_id`),
  KEY `extension_id` (`extension_id`)
) ENGINE=MyISAM AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_extension_rating`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_extension_rating`;
CREATE TABLE `oc_extension_rating` (
  `extension_rating_id` int NOT NULL AUTO_INCREMENT,
  `extension_id` int NOT NULL,
  `member_id` int NOT NULL,
  `order_id` int NOT NULL DEFAULT '0',
  `functionality` int NOT NULL DEFAULT '5',
  `appearance` int NOT NULL DEFAULT '5',
  `user_friendly` int NOT NULL DEFAULT '5',
  `support` int NOT NULL DEFAULT '5',
  `documentation` int NOT NULL DEFAULT '5',
  `rating` int NOT NULL DEFAULT '5',
  `comment` text NOT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`extension_rating_id`),
  KEY `extension_id` (`extension_id`)
) ENGINE=MyISAM AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_information`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_information`;
CREATE TABLE `oc_information` (
  `information_id` int NOT NULL AUTO_INCREMENT,
  `bottom` int NOT NULL DEFAULT '0',
  `sort_order` int NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`information_id`)
) ENGINE=MyISAM AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_information_description`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_information_description`;
CREATE TABLE `oc_information_description` (
  `information_id` int NOT NULL,
  `language_id` int NOT NULL,
  `title` varchar(64) NOT NULL,
  `description` mediumtext NOT NULL,
  `meta_title` varchar(255) NOT NULL,
  `meta_description` varchar(255) NOT NULL,
  `meta_keyword` varchar(255) NOT NULL,
  PRIMARY KEY (`information_id`,`language_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_information_to_store`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_information_to_store`;
CREATE TABLE `oc_information_to_store` (
  `information_id` int NOT NULL,
  `store_id` int NOT NULL,
  PRIMARY KEY (`information_id`,`store_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_language`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_language`;
CREATE TABLE `oc_language` (
  `language_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(32) NOT NULL,
  `code` varchar(5) NOT NULL,
  `locale` varchar(255) NOT NULL,
  `image` varchar(64) NOT NULL,
  `directory` varchar(32) NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL,
  PRIMARY KEY (`language_id`),
  KEY `name` (`name`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_mail_log`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_mail_log`;
CREATE TABLE `oc_mail_log` (
  `mail_log_id` int NOT NULL AUTO_INCREMENT,
  `recipient` varchar(255) NOT NULL,
  `sender` varchar(255) NOT NULL,
  `subject` varchar(255) NOT NULL,
  `engine` varchar(32) NOT NULL DEFAULT 'mail',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `error` text NOT NULL,
  `body` mediumtext NOT NULL,
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`mail_log_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_member`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_member`;
CREATE TABLE `oc_member` (
  `member_id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(64) NOT NULL,
  `firstname` varchar(32) NOT NULL,
  `lastname` varchar(32) NOT NULL,
  `company` varchar(128) NOT NULL DEFAULT '',
  `tax_id` varchar(64) NOT NULL DEFAULT '',
  `email` varchar(96) NOT NULL,
  `telephone` varchar(32) NOT NULL DEFAULT '',
  `image` varchar(255) NOT NULL DEFAULT '',
  `country_id` int NOT NULL DEFAULT '222',
  `password` varchar(40) NOT NULL,
  `salt` varchar(9) NOT NULL,
  `code` varchar(40) NOT NULL DEFAULT '',
  `pin` varchar(10) NOT NULL DEFAULT '',
  `pin_attempts` int NOT NULL DEFAULT '0',
  `notify` tinyint(1) NOT NULL DEFAULT '1',
  `verified` tinyint(1) NOT NULL DEFAULT '0',
  `seller_status` tinyint(1) NOT NULL DEFAULT '0',
  `partner_status` tinyint(1) NOT NULL DEFAULT '0',
  `moderator` tinyint(1) NOT NULL DEFAULT '0',
  `cloud` tinyint(1) NOT NULL DEFAULT '1',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `ip` varchar(40) NOT NULL DEFAULT '',
  `date_added` datetime NOT NULL,
  `date_modified` datetime NOT NULL,
  PRIMARY KEY (`member_id`),
  KEY `email` (`email`),
  KEY `username` (`username`)
) ENGINE=MyISAM AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_member_ip`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_member_ip`;
CREATE TABLE `oc_member_ip` (
  `member_ip_id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL,
  `ip` varchar(40) NOT NULL,
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`member_ip_id`),
  KEY `member_id` (`member_id`)
) ENGINE=MyISAM AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_member_login`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_member_login`;
CREATE TABLE `oc_member_login` (
  `member_login_id` int NOT NULL AUTO_INCREMENT,
  `email` varchar(96) NOT NULL,
  `ip` varchar(40) NOT NULL,
  `total` int NOT NULL,
  `date_added` datetime NOT NULL,
  `date_modified` datetime NOT NULL,
  PRIMARY KEY (`member_login_id`),
  KEY `email` (`email`),
  KEY `ip` (`ip`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_member_partner`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_member_partner`;
CREATE TABLE `oc_member_partner` (
  `member_partner_id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL,
  `member_partner_type_id` int NOT NULL DEFAULT '1',
  `member_partner_status_id` int NOT NULL DEFAULT '1',
  `firstname` varchar(32) NOT NULL,
  `lastname` varchar(32) NOT NULL,
  `company` varchar(128) NOT NULL,
  `website` varchar(255) NOT NULL,
  `email` varchar(96) NOT NULL,
  `telephone` varchar(32) NOT NULL,
  `description_short` text NOT NULL,
  `description_long` text NOT NULL,
  `address_1` varchar(128) NOT NULL,
  `address_2` varchar(128) NOT NULL DEFAULT '',
  `city` varchar(128) NOT NULL,
  `postcode` varchar(16) NOT NULL DEFAULT '',
  `country_id` int NOT NULL,
  `zone_id` int NOT NULL,
  `image` varchar(255) NOT NULL DEFAULT '',
  `facebook` varchar(255) NOT NULL DEFAULT '',
  `twitter` varchar(255) NOT NULL DEFAULT '',
  `linkedin` varchar(255) NOT NULL DEFAULT '',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `date_added` datetime NOT NULL,
  `date_modified` datetime NOT NULL,
  PRIMARY KEY (`member_partner_id`),
  KEY `member_id` (`member_id`)
) ENGINE=MyISAM AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_member_partner_status`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_member_partner_status`;
CREATE TABLE `oc_member_partner_status` (
  `member_partner_status_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL,
  `image` varchar(255) NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`member_partner_status_id`)
) ENGINE=MyISAM AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_member_partner_type`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_member_partner_type`;
CREATE TABLE `oc_member_partner_type` (
  `member_partner_type_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`member_partner_type_id`)
) ENGINE=MyISAM AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_member_payment`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_member_payment`;
CREATE TABLE `oc_member_payment` (
  `member_payment_id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL,
  `type` varchar(32) NOT NULL DEFAULT 'card',
  `name` varchar(128) NOT NULL,
  `token` varchar(128) NOT NULL,
  `image` varchar(255) NOT NULL,
  `date_expire` varchar(32) NOT NULL DEFAULT '',
  `default` tinyint(1) NOT NULL DEFAULT '0',
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`member_payment_id`),
  KEY `member_id` (`member_id`)
) ENGINE=MyISAM AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_member_seller`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_member_seller`;
CREATE TABLE `oc_member_seller` (
  `member_seller_id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL,
  `firstname` varchar(32) NOT NULL,
  `lastname` varchar(32) NOT NULL,
  `email` varchar(96) NOT NULL,
  `support_email` varchar(96) NOT NULL,
  `telephone` varchar(32) NOT NULL,
  `website` varchar(255) NOT NULL DEFAULT '',
  `payment_method` varchar(32) NOT NULL DEFAULT 'paypal',
  `payoneer_token` varchar(128) NOT NULL DEFAULT '',
  `payment_email` varchar(96) NOT NULL,
  `company` varchar(128) NOT NULL DEFAULT '',
  `address_1` varchar(128) NOT NULL,
  `address_2` varchar(128) NOT NULL DEFAULT '',
  `city` varchar(128) NOT NULL,
  `postcode` varchar(16) NOT NULL DEFAULT '',
  `country_id` int NOT NULL,
  `zone_id` int NOT NULL,
  `notify` tinyint(1) NOT NULL DEFAULT '1',
  `api_status` tinyint(1) NOT NULL DEFAULT '0',
  `api_url` varchar(255) NOT NULL DEFAULT '',
  `commission` int NOT NULL DEFAULT '20',
  `seller_group` varchar(64) NOT NULL DEFAULT 'Standard Seller (80%)',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `date_added` datetime NOT NULL,
  `date_modified` datetime NOT NULL,
  PRIMARY KEY (`member_seller_id`),
  KEY `member_id` (`member_id`)
) ENGINE=MyISAM AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_member_store`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_member_store`;
CREATE TABLE `oc_member_store` (
  `member_store_id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL,
  `domain` varchar(255) NOT NULL,
  `username` varchar(128) NOT NULL,
  `secret` text NOT NULL,
  `date_added` datetime NOT NULL,
  `date_modified` datetime NOT NULL,
  PRIMARY KEY (`member_store_id`),
  KEY `member_id` (`member_id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_member_transaction`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_member_transaction`;
CREATE TABLE `oc_member_transaction` (
  `member_transaction_id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL,
  `order_id` int NOT NULL DEFAULT '0',
  `description` varchar(255) NOT NULL,
  `amount` decimal(15,4) NOT NULL,
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`member_transaction_id`),
  KEY `member_id` (`member_id`)
) ENGINE=MyISAM AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_modification`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_modification`;
CREATE TABLE `oc_modification` (
  `modification_id` int NOT NULL AUTO_INCREMENT,
  `extension_install_id` int NOT NULL,
  `name` varchar(64) NOT NULL,
  `code` varchar(64) NOT NULL,
  `author` varchar(64) NOT NULL,
  `version` varchar(32) NOT NULL,
  `link` varchar(255) NOT NULL,
  `xml` mediumtext NOT NULL,
  `status` tinyint(1) NOT NULL,
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`modification_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_newsletter`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_newsletter`;
CREATE TABLE `oc_newsletter` (
  `newsletter_id` int NOT NULL AUTO_INCREMENT,
  `email` varchar(96) NOT NULL,
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`newsletter_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_order`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_order`;
CREATE TABLE `oc_order` (
  `order_id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL,
  `seller_id` int NOT NULL,
  `extension_id` int NOT NULL,
  `extension` varchar(128) NOT NULL,
  `quantity` int NOT NULL DEFAULT '1',
  `price` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `total` decimal(15,4) NOT NULL DEFAULT '0.0000',
  `payment_method` varchar(64) NOT NULL DEFAULT 'PayPal',
  `transaction_id` varchar(128) NOT NULL DEFAULT '',
  `order_status_id` int NOT NULL DEFAULT '5',
  `ip` varchar(40) NOT NULL DEFAULT '',
  `date_added` datetime NOT NULL,
  `date_modified` datetime NOT NULL,
  PRIMARY KEY (`order_id`),
  KEY `member_id` (`member_id`),
  KEY `seller_id` (`seller_id`),
  KEY `extension_id` (`extension_id`)
) ENGINE=MyISAM AUTO_INCREMENT=1003 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_order_status`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_order_status`;
CREATE TABLE `oc_order_status` (
  `order_status_id` int NOT NULL AUTO_INCREMENT,
  `language_id` int NOT NULL,
  `name` varchar(32) NOT NULL,
  PRIMARY KEY (`order_status_id`,`language_id`)
) ENGINE=MyISAM AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_seo_url`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_seo_url`;
CREATE TABLE `oc_seo_url` (
  `seo_url_id` int NOT NULL AUTO_INCREMENT,
  `store_id` int NOT NULL,
  `language_id` int NOT NULL,
  `query` varchar(255) NOT NULL,
  `keyword` varchar(255) NOT NULL,
  PRIMARY KEY (`seo_url_id`),
  KEY `query` (`query`),
  KEY `keyword` (`keyword`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_session`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_session`;
CREATE TABLE `oc_session` (
  `session_id` varchar(32) NOT NULL,
  `data` text NOT NULL,
  `expire` datetime NOT NULL,
  PRIMARY KEY (`session_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_setting`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_setting`;
CREATE TABLE `oc_setting` (
  `setting_id` int NOT NULL AUTO_INCREMENT,
  `store_id` int NOT NULL DEFAULT '0',
  `code` varchar(128) NOT NULL,
  `key` varchar(128) NOT NULL,
  `value` text NOT NULL,
  `serialized` tinyint(1) NOT NULL,
  PRIMARY KEY (`setting_id`)
) ENGINE=MyISAM AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_showcase`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_showcase`;
CREATE TABLE `oc_showcase` (
  `showcase_id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL,
  `showcase_category_id` int NOT NULL,
  `name` varchar(128) NOT NULL,
  `link` varchar(255) NOT NULL,
  `image` varchar(255) NOT NULL,
  `date_launch` date NOT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`showcase_id`),
  KEY `showcase_category_id` (`showcase_category_id`),
  KEY `member_id` (`member_id`)
) ENGINE=MyISAM AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_showcase_category`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_showcase_category`;
CREATE TABLE `oc_showcase_category` (
  `showcase_category_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`showcase_category_id`)
) ENGINE=MyISAM AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_statistics`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_statistics`;
CREATE TABLE `oc_statistics` (
  `statistics_id` int NOT NULL AUTO_INCREMENT,
  `code` varchar(64) NOT NULL,
  `value` decimal(15,4) NOT NULL,
  PRIMARY KEY (`statistics_id`)
) ENGINE=MyISAM AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_store`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_store`;
CREATE TABLE `oc_store` (
  `store_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL,
  `url` varchar(255) NOT NULL,
  `ssl` varchar(255) NOT NULL,
  PRIMARY KEY (`store_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_subscription`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_subscription`;
CREATE TABLE `oc_subscription` (
  `subscription_id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NOT NULL,
  `subscription_plan_id` int NOT NULL,
  `member_payment_id` int NOT NULL DEFAULT '1',
  `subscription_status_id` int NOT NULL DEFAULT '1',
  `name` varchar(128) NOT NULL,
  `admin_email` varchar(96) NOT NULL,
  `admin_username` varchar(64) NOT NULL,
  `store_status` varchar(32) NOT NULL DEFAULT 'running',
  `date_added` datetime NOT NULL,
  `date_modified` datetime NOT NULL,
  PRIMARY KEY (`subscription_id`),
  KEY `member_id` (`member_id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_subscription_backup`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_subscription_backup`;
CREATE TABLE `oc_subscription_backup` (
  `backup_id` int NOT NULL AUTO_INCREMENT,
  `subscription_id` int NOT NULL,
  `type` varchar(32) NOT NULL DEFAULT 'file',
  `status` varchar(32) NOT NULL DEFAULT 'complete',
  `created` datetime NOT NULL,
  PRIMARY KEY (`backup_id`),
  KEY `subscription_id` (`subscription_id`)
) ENGINE=MyISAM AUTO_INCREMENT=103 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_subscription_domain`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_subscription_domain`;
CREATE TABLE `oc_subscription_domain` (
  `subscription_domain_id` int NOT NULL AUTO_INCREMENT,
  `subscription_id` int NOT NULL DEFAULT '0',
  `member_id` int NOT NULL,
  `name` varchar(255) NOT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'active',
  `pointed` tinyint(1) NOT NULL DEFAULT '1',
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`subscription_domain_id`),
  KEY `member_id` (`member_id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_subscription_history`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_subscription_history`;
CREATE TABLE `oc_subscription_history` (
  `subscription_history_id` int NOT NULL AUTO_INCREMENT,
  `subscription_id` int NOT NULL,
  `status` varchar(64) NOT NULL,
  `comment` text NOT NULL,
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`subscription_history_id`),
  KEY `subscription_id` (`subscription_id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_subscription_plan`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_subscription_plan`;
CREATE TABLE `oc_subscription_plan` (
  `subscription_plan_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL,
  `description` text NOT NULL,
  `price` decimal(15,2) NOT NULL DEFAULT '0.00',
  `label_active` tinyint(1) NOT NULL DEFAULT '0',
  `sort_order` int NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`subscription_plan_id`)
) ENGINE=MyISAM AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_subscription_status`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_subscription_status`;
CREATE TABLE `oc_subscription_status` (
  `subscription_status_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL,
  PRIMARY KEY (`subscription_status_id`)
) ENGINE=MyISAM AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_subscription_transaction`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_subscription_transaction`;
CREATE TABLE `oc_subscription_transaction` (
  `subscription_transaction_id` int NOT NULL AUTO_INCREMENT,
  `subscription_id` int NOT NULL,
  `member_id` int NOT NULL,
  `transaction_id` varchar(128) NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `store_name` varchar(128) NOT NULL,
  `transaction_card` varchar(128) NOT NULL,
  `transaction_card_image` varchar(255) NOT NULL,
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`subscription_transaction_id`),
  KEY `member_id` (`member_id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_support_enquiry`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_support_enquiry`;
CREATE TABLE `oc_support_enquiry` (
  `enquiry_id` int NOT NULL AUTO_INCREMENT,
  `type` varchar(32) NOT NULL DEFAULT 'contact',
  `reason` varchar(64) NOT NULL DEFAULT '',
  `partner_id` int NOT NULL DEFAULT '0',
  `name` varchar(128) NOT NULL,
  `email` varchar(96) NOT NULL,
  `telephone` varchar(64) NOT NULL DEFAULT '',
  `company` varchar(128) NOT NULL DEFAULT '',
  `website` varchar(255) NOT NULL DEFAULT '',
  `country_id` int NOT NULL DEFAULT '0',
  `order_id` varchar(64) NOT NULL DEFAULT '',
  `version_id` int NOT NULL DEFAULT '0',
  `extension_url` varchar(255) NOT NULL DEFAULT '',
  `original_url` varchar(255) NOT NULL DEFAULT '',
  `subject` varchar(255) NOT NULL DEFAULT '',
  `enquiry` text NOT NULL,
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`enquiry_id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_translation`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_translation`;
CREATE TABLE `oc_translation` (
  `translation_id` int NOT NULL AUTO_INCREMENT,
  `store_id` int NOT NULL,
  `language_id` int NOT NULL,
  `route` varchar(64) NOT NULL,
  `key` varchar(64) NOT NULL,
  `value` text NOT NULL,
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`translation_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_upload`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_upload`;
CREATE TABLE `oc_upload` (
  `upload_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `filename` varchar(255) NOT NULL,
  `code` varchar(255) NOT NULL,
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`upload_id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

-- --------------------------------------------------------
-- Table structure for `oc_user`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_user`;
CREATE TABLE `oc_user` (
  `user_id` int NOT NULL AUTO_INCREMENT,
  `user_group_id` int NOT NULL,
  `username` varchar(20) NOT NULL,
  `password` varchar(40) NOT NULL,
  `salt` varchar(9) NOT NULL,
  `firstname` varchar(32) NOT NULL,
  `lastname` varchar(32) NOT NULL,
  `email` varchar(96) NOT NULL,
  `image` varchar(255) NOT NULL,
  `code` varchar(40) NOT NULL,
  `ip` varchar(40) NOT NULL,
  `status` tinyint(1) NOT NULL,
  `date_added` datetime NOT NULL,
  PRIMARY KEY (`user_id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_user_group`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_user_group`;
CREATE TABLE `oc_user_group` (
  `user_group_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(64) NOT NULL,
  `permission` text NOT NULL,
  PRIMARY KEY (`user_group_id`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3;


-- --------------------------------------------------------
-- Table structure for `oc_zone`
-- --------------------------------------------------------

DROP TABLE IF EXISTS `oc_zone`;
CREATE TABLE `oc_zone` (
  `zone_id` int NOT NULL AUTO_INCREMENT,
  `country_id` int NOT NULL,
  `name` varchar(128) NOT NULL,
  `code` varchar(32) NOT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`zone_id`)
) ENGINE=MyISAM AUTO_INCREMENT=4239 DEFAULT CHARSET=utf8mb3;


