INSERT INTO `oc_banner_image` (`banner_image_id`, `banner_id`, `language_id`, `title`, `link`, `image`, `sort_order`) VALUES
('1', '1', '1', 'PayPal Checkout Integration for OpenCart', 'index.php?route=marketplace/extension/info&extension_id=38358', 'application/view/image/banner/paypal_banner_large.jpg', '1');
INSERT INTO `oc_blog` (`blog_id`, `blog_category_id`, `title`, `description`, `author`, `image`, `image_status`, `trending`, `viewed`, `status`, `date_added`, `date_modified`) VALUES
('301', '3', 'Why recurring revenue is rewriting the rules for ecommerce stores in 2026', '<p><strong>Core insights</strong></p><p>Recurring purchases, from subscription boxes to auto-replenishment, have become one of the biggest growth levers in ecommerce, because keeping a customer now costs far less than winning a new one.</p><p>The catch sits in the back office. Billing cycles multiply, invoices pile up, and manual tracking quickly breaks down without native subscription automation in OpenCart 4.</p>', 'Opencart', 'catalog/blog/blog_1.jpg', '1', '0', '1420', '1', '2026-10-13 10:00:00', '2026-10-13 10:00:00'),
('302', '3', 'How to increase your ecommerce conversion rate', '<p><strong>Core insights</strong></p><p>Conversion rate is the lowest-cost growth lever a store has. Lifting it costs nothing per extra order, while buying the same growth in traffic costs more every month and stops the day you stop paying.</p><p>Most of the leak is at checkout, and most of that is cost surprise. Baymard Institute research shows transparent shipping and streamlined one-page checkouts recover up to 35% of lost orders.</p>', 'Opencart', 'catalog/blog/blog_2.jpg', '1', '0', '1280', '1', '2026-10-13 09:00:00', '2026-10-13 09:00:00'),
('303', '1', 'How to launch an ecommerce business: financial planning and digital tools', '<p><strong>Core insights</strong></p><p>Products are rarely the only major startup cost. Website setup, packaging, photography, software subscriptions and several months of marketing all belong in the budget before launch day, not after.</p><p>Choosing a platform is a financial decision as much as a technical one. Transaction fees on hosted platforms compound rapidly compared to open-source OpenCart.</p>', 'Opencart', 'catalog/blog/blog_3.jpg', '1', '0', '980', '1', '2026-10-10 10:00:00', '2026-10-10 10:00:00'),
('304', '4', 'How Get Started HK Helps E-Commerce Founders Set Up for International Growth', '<p>For overseas entrepreneurs, setting up an e-commerce business in Hong Kong may initially seem straightforward: incorporate a company, arrange payment collection, launch a store, and begin selling. In practice, these steps are interconnected. A company can be legally registered but still lack the compliance documentation required by international payment gateways.</p>', 'Opencart', 'catalog/blog/blog_4.jpg', '1', '0', '860', '1', '2026-10-06 10:00:00', '2026-10-06 10:00:00'),
('305', '3', 'Your OpenCart shoppers drop off at checkout? Here is a fix', '<p><strong>Core insights</strong></p><p>Cart abandonment is the single most costly leak in ecommerce revenue. Baymard Institute, aggregating data across 50 studies, puts the average abandonment rate at 70.22%, and most of that drop-off traces back to answerable problems with cost, delivery, or the checkout itself.</p>', 'Opencart', 'catalog/blog/blog_5.jpg', '1', '0', '1150', '1', '2026-10-02 10:00:00', '2026-10-02 10:00:00'),
('306', '1', 'How to migrate from WooCommerce to OpenCart', '<p><strong>Core insights</strong></p><p>Moving from WooCommerce to OpenCart trades a store that runs inside WordPress for a standalone commerce application, while keeping the ownership and the no-platform-fee model you already have.</p><p>Products, customers and orders move with a migration tool. The real work is the theme, SEO URL redirects, and payment gateway configuration.</p>', 'Opencart', 'catalog/blog/blog_6.jpg', '1', '0', '1540', '1', '2026-10-01 10:00:00', '2026-10-01 10:00:00'),
('307', '4', 'How specialist online stores can build trust and compete in technical ecommerce', '<p><strong>Core insights</strong></p><p>Technical buyers cannot shop from photographs. A wrong component means a return, a delayed installation, and sometimes a safety problem, so the specification table has to do the job a knowledgeable counter assistant used to do in person.</p><p>Filtering on real attributes, voltage, dimensions, and compatibility is where OpenCart excels.</p>', 'Opencart', 'catalog/blog/blog_7.jpg', '1', '0', '790', '1', '2026-09-29 10:00:00', '2026-09-29 10:00:00'),
('308', '1', 'How to start a dropshipping store', '<p><strong>Core insights</strong></p><p>The first sign a warehouse has outgrown its process is usually a stock count that no longer matches the shelf. Spreadsheets and memory work at a dozen orders a day and stop working long before most merchants notice.</p><p>Sequence matters more than hardware. Fix visibility first, because automated supplier feeds keep your storefront accurate.</p>', 'Opencart', 'catalog/blog/blog_8.jpg', '1', '0', '1320', '1', '2026-09-22 10:00:00', '2026-09-22 10:00:00'),
('309', '3', 'When your online store outgrows its warehouse: a practical', '<p><strong>Core insights</strong></p><p>The first sign a warehouse has outgrown its process is usually a stock count that no longer matches the shelf. Spreadsheets and memory work at a dozen orders a day and stop working long before most merchants notice.</p><p>Sequence matters more than hardware. Fix visibility first, because bin locations and barcode scanning depend on clean inventory records.</p>', 'Opencart', 'catalog/blog/blog_9.jpg', '1', '0', '940', '1', '2026-09-21 10:00:00', '2026-09-21 10:00:00'),
('310', '5', 'How to install OpenCart, step by step', '<p><strong>Core insights</strong></p><p>Installing OpenCart takes one of two routes: a one-click install through your host’s app installer, or a manual install by uploading the files and running the setup wizard.</p><p>You need hosting that supports PHP 8 and a database, which is ordinary shared hosting, plus the free OpenCart download package.</p>', 'Opencart', 'catalog/blog/blog_10.jpg', '1', '0', '2450', '1', '2026-09-18 10:00:00', '2026-09-18 10:00:00'),
('32', '2', 'Nominate OpenCart for Favorite Open Source Business Application', '<p>OpenCart continues to lead the open-source eCommerce community worldwide. Join thousands of merchants and developers in nominating OpenCart for Favorite Open Source Business Application.</p>', 'Opencart', 'catalog/blog/blog_1.jpg', '1', '1', '9800', '1', '2023-11-15 10:00:00', '2023-11-15 10:00:00'),
('200', '2', 'OpenCart Version 3.0.0.0 Available to Download Now', '<p>OpenCart 3.0.0.0 is officially available to download! Featuring an integrated Extension Marketplace, Theme Editor, Language Editor, Multilingual SEO URLs, and the Twig template engine.</p>', 'Opencart', 'catalog/blog/blog_2.jpg', '1', '1', '28500', '1', '2023-10-20 10:00:00', '2023-10-20 10:00:00'),
('205', '3', '7 Tips to Maximize Multi-Channel Efforts', '<p>Selling across multiple channels such as Amazon, eBay, Google Shopping, and Facebook Shop requires synchronized inventory, unified order management, and consistent product data.</p>', 'Opencart', 'catalog/blog/blog_3.jpg', '1', '1', '11200', '1', '2023-09-18 10:00:00', '2023-09-18 10:00:00'),
('206', '5', 'What is new in OpenCart: How to Setup SEO URLs in OpenCart 3.x', '<p>Learn how to enable and configure SEO URLs in OpenCart 3.x and 4.x using .htaccess and the built-in Design &gt; SEO URL manager for multi-store and multi-language setups.</p>', 'Opencart', 'catalog/blog/blog_4.jpg', '1', '1', '19400', '1', '2023-08-25 10:00:00', '2023-08-25 10:00:00'),
('137', '4', '7 Live Examples of OpenCart eCommerce Websites', '<p>Explore 7 inspiring live OpenCart online stores across fashion, electronics, food &amp; beverage, and automotive industries demonstrating the flexibility of OpenCart.</p>', 'Opencart', 'catalog/blog/blog_5.jpg', '1', '1', '16800', '1', '2023-07-14 10:00:00', '2023-07-14 10:00:00'),
('210', '1', 'Build Your eCommerce Website In a Free and Customizable Manner', '<p>Create a fully customizable free eCommerce website. The eCommerce landscape is witnessing phenomenal growth, underlining the importance of retailing online with full ownership of your store.</p>', 'Joshua', 'catalog/blog/blog_6.jpg', '1', '1', '14300', '1', '2023-06-11 10:00:00', '2023-06-11 10:00:00'),
('207', '5', 'What is new in OpenCart: How to Install a Theme in OpenCart 3.x', '<p>Step-by-step video and written tutorial on how to install, activate, and customize a new OpenCart theme using the Extension Installer and Theme Editor.</p>', 'Opencart', 'catalog/blog/blog_7.jpg', '1', '1', '15900', '1', '2023-05-09 10:00:00', '2023-05-09 10:00:00'),
('157', '2', 'OpenCart Version 2.3.0.2 Available to Download Now', '<p>OpenCart 2.3.0.2 is available to download with stability improvements, updated payment modules, and enhanced extension compatibility.</p>', 'Opencart', 'catalog/blog/blog_8.jpg', '1', '1', '12100', '1', '2023-04-02 10:00:00', '2023-04-02 10:00:00');
