INSERT INTO `oc_download` (`download_id`, `name`, `description`, `filename`, `mask`, `href`, `date_added`) VALUES
('82', '4.1.0.4', 'OpenCart 4.1.0.4 Release Notes:<br />\n- Improved PHP 8.3 &amp; 8.4 compatibility and performance optimizations.<br />\n- Updated Marketplace API and extension installer.<br />\n- Fixed checkout session, tax calculation, and subscription renewal edge cases.<br />\n- Full change list: https://github.com/opencart/opencart/releases/tag/4.1.0.4', 'opencart-4.1.0.4.zip', 'opencart-4.1.0.4.zip', 'https://github.com/opencart/opencart/releases/download/4.1.0.4/opencart-4.1.0.4.zip', '2026-08-11 10:00:00'),
('81', '3.0.5.1', 'OpenCart 3.0.5.1 Maintenance Release:<br />\n- PHP 8.2 / 8.3 compatibility fixes for OpenCart 3.0.x branch.<br />\n- Security and payment gateway callback improvements.<br />\n- Full change list: https://github.com/opencart/opencart/releases/tag/3.0.5.1', 'opencart-3.0.5.1.zip', 'opencart-3.0.5.1.zip', 'https://github.com/opencart/opencart/releases/download/3.0.5.1/opencart-3.0.5.1.zip', '2026-07-20 10:00:00'),
('80', '3.0.5.0', 'OpenCart 3.0.5.0 Release:<br />\n- Backported security and performance improvements to the 3.0.x LTS branch.<br />\n- Updated default payment and shipping extensions.<br />\n- Full change list: https://github.com/opencart/opencart/releases/tag/3.0.5.0', 'opencart-3.0.5.0.zip', 'opencart-3.0.5.0.zip', 'https://github.com/opencart/opencart/releases/download/3.0.5.0/opencart-3.0.5.0.zip', '2026-07-02 10:00:00'),
('79', '3.0.4.1', 'OpenCart 3.0.4.1 Release:<br />\n- Bug fixes for OpenCart 3.0.4.0.<br />\n- Improved Twig template engine compatibility with PHP 8.2+.<br />\n- Full change list: https://github.com/opencart/opencart/releases/tag/3.0.4.1', '3.0.4.1.zip', '3.0.4.1.zip', 'https://github.com/opencart/opencart/releases/download/3.0.4.1/3.0.4.1.zip', '2026-05-15 10:00:00'),
('78', '4.1.0.3', '## What&#039;s Changed<br />\r\n* More PHPDocs work by @TheCartpenter in https://github.com/opencart/opencart/pull/14700<br />\r\n* [fix] The update procedure does not work by @batumibiz in https://github.com/opencart/opencart/pull/14703<br />\r\n* Modified upgrade/upgrade PHPDocs by @TheCartpenter in https://github.com/opencart/opencart/pull/14708<br />\r\n* Update to admin marketplace/installer.php by @milsaware in https://github.com/opencart/opencart/pull/14709<br />\r\n* removed country_id by @farshadfmr in https://github.com/opencart/opencart/pull/14713<br />\r\n* Removed identifier_id in PHPDocs of getIdentifierByCode method in model/identifier by @TheCartpenter in https://github.com/opencart/opencart/pull/14714<br />\r\n* Removed country_id and zone_id from deleteDescriptionsByLanguageId PHPDocs by @TheCartpenter in https://github.com/opencart/opencart/pull/14717<br />\r\n* Modified localisation/country controller and model delete descriptions method by @TheCartpenter in https://github.com/opencart/opencart/pull/14720<br />\r\n* More model comments work by @TheCartpenter in https://github.com/opencart/opencart/pull/14725<br />\r\n* More PHPDocs work and fixed some package paths in extensions by @TheCartpenter in https://github.com/opencart/opencart/pull/14726<br />\r\n* More PHPDocs work by @TheCartpenter in https://github.com/opencart/opencart/pull/14727<br />\r\n<br />\r\n## New Contributors<br />\r\n* @milsaware made their first contribution in https://github.com/opencart/opencart/pull/14709<br />\r\n* @farshadfmr made their first contribution in https://github.com/opencart/opencart/pull/14713<br />\r\n<br />\r\n**Full Changelog**: https://github.com/opencart/opencart/compare/4.1.0.2...4.1.0.3', 'opencart-4.1.0.3.zip', 'opencart-4.1.0.3.zip', 'https://github.com/opencart/opencart/releases/download/4.1.0.3/opencart-4.1.0.3.zip', '2026-03-24 12:12:41'),
('77', '4.1.0.2', 'Full change list:<br />\nhttps://github.com/opencart/opencart/releases/tag/4.1.0.2', 'opencart-4.1.0.2.zip', 'opencart-4.1.0.2.zip', 'https://github.com/opencart/opencart/releases/download/4.1.0.2/opencart-4.1.0.2.zip', '2026-02-18 10:00:00'),
('76', '4.1.0.1', 'Full change list:<br />\nhttps://github.com/opencart/opencart/releases/tag/4.1.0.1', 'opencart-4.1.0.1.zip', 'opencart-4.1.0.1.zip', 'https://github.com/opencart/opencart/releases/download/4.1.0.1/opencart-4.1.0.1.zip', '2026-01-22 10:00:00'),
('75', '4.1.0.0', 'ADDED<br />\r\nOCMOD back!!<br />\r\nFrench language<br />\r\nBlog system<br />\r\n <br />\r\nUPDATED<br />\r\norder editor. normalised the ordered editor system. <br />\r\n<br />\r\nFIXED<br />\r\nSubscription system<br />\r\n<br />\r\nPlease read release notes for full list<br />\r\n<br />\r\n## What&#039;s Changed<br />\r\n* Fix Zone list - status always &quot;Enabled&quot; by @batumibiz in https://github.com/opencart/opencart/pull/12694<br />\r\n* CKEditor ShowBlocks alternate config by @stalker780 in https://github.com/opencart/opencart/pull/12693<br />\r\n* Remove German language test files /extension/opencart/catalog/language/de-de by @pemaier in https://github.com/opencart/opencart/pull/12699<br />\r\n* Removed unused variable from common/column_left by @SecretSergey in https://github.com/opencart/opencart/pull/12723<br />\r\n* Update review.php by @tmdashwani in https://github.com/opencart/opencart/pull/12703<br />\r\n* Added int cast in cms/comment by @TheCartpenter in https://github.com/opencart/opencart/pull/12716<br />\r\n* [Master] Added missing language variable cms/blog by @condor2 in https://github.com/opencart/opencart/pull/12711<br />\r\n* Update robots.txt by @chongshengdz in https://github.com/opencart/opencart/pull/12732<br />\r\n* Update forgotten.php by @rahulabs in https://github.com/opencart/opencart/pull/12705<br />\r\n* Renamed Apcu class in library/cache/apcu by @TheCartpenter in https://github.com/opencart/opencart/pull/12722<br />\r\n* Update subscription.php by @rahulabs in https://github.com/opencart/opencart/pull/12704<br />\r\n* Update setting.php by @Cubuss in https://github.com/opencart/opencart/pull/12735<br />\r\n* Update comment.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12747<br />\r\n* Update forgotten.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12737<br />\r\n* Fixed an error in the SQL query by @batumibiz in https://github.com/opencart/opencart/pull/12756<br />\r\n* Fix anti-spam validate in the Returns page by @willdevx in https://github.com/opencart/opencart/pull/12752<br />\r\n* Update opencart.sql - updated image_topic_width from D to 1140 by @pemaier in https://github.com/opencart/opencart/pull/12753<br />\r\n* Update location_form.twig by @stalker780 in https://github.com/opencart/opencart/pull/12760<br />\r\n* #12757 mysql ssl connection support by @fmarslan in https://github.com/opencart/opencart/pull/12758<br />\r\n* Removed empty trailing lines. by @TheCartpenter in https://github.com/opencart/opencart/pull/12748<br />\r\n* error vendor uninstaller.php by @BuslikDrev in https://github.com/opencart/opencart/pull/12654<br />\r\n* More code alignments by @TheCartpenter in https://github.com/opencart/opencart/pull/12761<br />\r\n* Update setting.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12770<br />\r\n* Update cli_install.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12776<br />\r\n* Update step_2.twig by @TheCartpenter in https://github.com/opencart/opencart/pull/12775<br />\r\n* Fixed Tax and Zone Date by @ppalashturov in https://github.com/opencart/opencart/pull/12786<br />\r\n* Update comment.php by @opencartbot in https://github.com/opencart/opencart/pull/12783<br />\r\n* README.md - License link updated by @pemaier in https://github.com/opencart/opencart/pull/12803<br />\r\n* Fix message &quot;PHP7.4 Required&quot; by @opencartbot in https://github.com/opencart/opencart/pull/12794<br />\r\n* Update product.php by @stalker780 in https://github.com/opencart/opencart/pull/12801<br />\r\n* Delete the last comma by @opencartbot in https://github.com/opencart/opencart/pull/12793<br />\r\n* Update index.php and fixed Model Filter by @ppalashturov in https://github.com/opencart/opencart/pull/12789<br />\r\n* Blogs $limit from &#039;config_pagination&#039; by @opencartbot in https://github.com/opencart/opencart/pull/12790<br />\r\n* Add skipped &#039;error_author&#039; translation by @opencartbot in https://github.com/opencart/opencart/pull/12792<br />\r\n* Update user.php by @rahulabs in https://github.com/opencart/opencart/pull/12814<br />\r\n* Update default.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12817<br />\r\n* Update developer.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12838<br />\r\n* Update gdpr.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12842<br />\r\n* Sticky admin filters by @stalker780 in https://github.com/opencart/opencart/pull/12807<br />\r\n* Admin - escape aliases by @stalker780 in https://github.com/opencart/opencart/pull/12808<br />\r\n* Update user.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12843<br />\r\n* Update bestseller.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12847<br />\r\n* Update affiliate.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12822<br />\r\n* Update forgotten.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12823<br />\r\n* Update currency.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12848<br />\r\n* Update cron.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12825<br />\r\n* Update product.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12846<br />\r\n* Update dashboard.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12824<br />\r\n* Update subscription.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12826<br />\r\n* Update store.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12827<br />\r\n* Update returns.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12836<br />\r\n* Update customer.php by @stalker780 in https://github.com/opencart/opencart/pull/12856<br />\r\n* Update download.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12828<br />\r\n* Update cookie.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12829<br />\r\n* Update country.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12834<br />\r\n* Update customer_approval.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12835<br />\r\n* Update opencart.sql - Added extension/modul/topic by @pemaier in https://github.com/opencart/opencart/pull/12830<br />\r\n* Update default.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12840<br />\r\n* Update marketplace.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12841<br />\r\n* Update security.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12839<br />\r\n* Update register.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12844<br />\r\n* Update wishlist.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12845<br />\r\n* Update language.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12850<br />\r\n* Update download.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12860<br />\r\n* Update language.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12849<br />\r\n* Update subscription.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12857<br />\r\n* Update order.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12862<br />\r\n* Update sale.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12858<br />\r\n* Update order.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12859<br />\r\n* Update order.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12861<br />\r\n* Update product_purchased.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12864<br />\r\n* Update customer_transaction.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12867<br />\r\n* Update ecb.php by @TheCartpenter in https://github.com/opencart/opencart/pull/12872<br />