INSERT INTO `oc_extension` (`extension_id`, `member_id`, `extension_category_id`, `name`, `description`, `documentation`, `history`, `license`, `license_period`, `price`, `image`, `banner`, `tag`, `cloud`, `recommended`, `featured`, `publish`, `notify`, `alert`, `sales`, `downloaded`, `rating`, `rating_total`, `reviews_enabled`, `comments_enabled`, `status`, `date_added`, `date_modified`) VALUES
('9132', '1', '22', 'AJAX Quick Checkout PRO (One Page Checkout, Fast Checkout)', '<p>The number 1 checkout extension on the market. We have been the best selling extension on OpenCart Marketplace for over 10 years. Boost your store conversion rate with a customizable one-page checkout experience.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>AJAX Quick Checkout PRO (One Page Checkout, Fast Checkout)</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '110.9900', 'catalog/marketplace/ext_9132.jpg', 'catalog/marketplace/ext_9132.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '8420', '12500', '4', '414', '1', '1', '1', '2023-05-10 10:00:00', '2026-08-15 10:00:00'),
('31314', '2', '8', 'Export-Import to Excel PRO: products, categories, attributes ...', '<p>Export-Import to Excel PRO: products, categories, attributes, options, filters, customers and orders. Fast bulk spreadsheet editing for OpenCart stores of any size.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Export-Import to Excel PRO: products, categories, attributes ...</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '132.9900', 'catalog/marketplace/ext_31314.jpg', 'catalog/marketplace/ext_31314.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '640', '920', '4', '7', '1', '1', '1', '2023-06-12 10:00:00', '2026-08-10 10:00:00'),
('29764', '1', '24', 'SEO Module URL', '<p>SEO Module URL for OpenCart: clean friendly URLs, automatic meta tags, canonical links, and multi-language SEO optimization.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>SEO Module URL</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '78.9900', 'catalog/marketplace/ext_29764.jpg', 'catalog/marketplace/ext_29764.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '530', '810', '4', '9', '1', '1', '1', '2023-04-20 10:00:00', '2026-08-05 10:00:00'),
('40361', '2', '1', 'Winehub Opencart Responsive Theme (Bar, Restaurant, Club)', '<p>Winehub Opencart Responsive Theme is specially designed for any multipurpose shop like wine shop, Club, Restaurant, drink zone, food Zone etc.. Winehub opencart theme comes with fully responsive, clean and elegant design and also additional features.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Winehub Opencart Responsive Theme (Bar, Restaurant, Club)</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '29.9900', 'catalog/marketplace/ext_40361.jpg', 'catalog/marketplace/ext_40361.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '120', '210', '0', '0', '1', '1', '1', '2024-01-15 10:00:00', '2026-07-12 10:00:00'),
('37931', '1', '1', 'Antropy Multipurpose Theme', '<p>Antropy Multipurpose Responsive OpenCart Theme. This theme will work with all the extensions as we haven\'t edited any of OpenCart\'s core files and theme files. Theme Features - Fully Responsive (Mobile and Tablet tested).</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Antropy Multipurpose Theme</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '34.9900', 'catalog/marketplace/ext_37931.jpg', 'catalog/marketplace/ext_37931.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '245', '390', '0', '3', '1', '1', '1', '2024-02-10 10:00:00', '2026-07-20 10:00:00'),
('40345', '2', '1', 'Tobis Furniture Ecommrce Opencart Website Template', '<p>Tobis Furniture is a Multipurpose Ecommerce Opencart Theme for any online Shop(website) such as wood, furniture, light, animated furniture, acrylic, architech design, etc. Tobis opencart theme comes with Pre made layout with fully responsive, clean design.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Tobis Furniture Ecommrce Opencart Website Template</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '29.9900', 'catalog/marketplace/ext_40345.jpg', 'catalog/marketplace/ext_40345.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '98', '150', '0', '0', '1', '1', '1', '2024-03-05 10:00:00', '2026-07-18 10:00:00'),
('45030', '1', '1', 'CiMarket – Light & Dark OpenCart Theme', '<p>CiMarket is a premium, modern, and highly customizable OpenCart 3.x, 4.x theme designed to meet the needs of any type of online store. It offers a responsive and elegant user experience across all devices. With a focus on performance, flexibility and clean code.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>CiMarket – Light &amp; Dark OpenCart Theme</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '34.9900', 'catalog/marketplace/ext_45030.jpg', 'catalog/marketplace/ext_45030.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '310', '480', '0', '3', '1', '1', '1', '2024-05-12 10:00:00', '2026-08-01 10:00:00'),
('45326', '2', '1', 'Accura Carbon V-1 Multipurpose Theme', '<p>Accura Carbon Multipurpose Responsive OpenCart Theme - Version 1. Theme Features: Simple & Clean Theme with Modern Design, Fully Responsive & Easy to Install, Category Product Slider Module, Sticker for Special Priced products, Logo.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Accura Carbon V-1 Multipurpose Theme</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '19.9900', 'catalog/marketplace/ext_45326.jpg', 'catalog/marketplace/ext_45326.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '175', '260', '0', '2', '1', '1', '1', '2024-06-18 10:00:00', '2026-08-03 10:00:00'),
('45330', '2', '1', 'Accura Ocean V-1 Multipurpose Theme', '<p>Accura Ocean Multipurpose Responsive OpenCart Theme - Version 1. Theme Features: Simple & Clean Theme with Modern Design, Fully Responsive & Easy to Install, Category Product Slider Module, Sticker for Special Priced products, Logo, Additional banners.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Accura Ocean V-1 Multipurpose Theme</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '19.9900', 'catalog/marketplace/ext_45330.jpg', 'catalog/marketplace/ext_45330.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '140', '220', '0', '0', '1', '1', '1', '2024-06-20 10:00:00', '2026-08-04 10:00:00'),
('32336', '1', '23', 'Facebook for OpenCart', '<p>Installing the Facebook Business Extension. Refer to our simplified installation guide for the steps to install the extension on your OpenCart store. Sync your catalog to Facebook & Instagram Shop and track conversions with Meta Pixel.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Facebook for OpenCart</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '0', '12', '0.0000', 'catalog/marketplace/ext_32336.jpg', 'catalog/marketplace/ext_32336.jpg', 'opencart,extension,marketplace', '1', '1', '1', '1', '1', '1', '0', '45200', '4', '31', '1', '1', '1', '2023-08-01 10:00:00', '2026-08-25 10:00:00'),
('38358', '1', '3', 'PayPal Checkout Integration', '<p>Help drive conversion. With 400M+ active accounts and global recognition, PayPal helps you reach more customers and boost sales. 46% higher checkout conversion with PayPal. Power AOV with Pay Later.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>PayPal Checkout Integration</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '0', '12', '0.0000', 'catalog/marketplace/ext_38358.jpg', 'catalog/marketplace/ext_38358.jpg', 'opencart,extension,marketplace', '1', '1', '1', '1', '1', '1', '0', '68400', '4', '44', '1', '1', '1', '2023-09-15 10:00:00', '2026-08-24 10:00:00'),
('49866', '1', '24', 'Abandoned Cart Recovery Pro', '<p>Abandoned Cart Recovery Pro - automatically recover lost sales with scheduled email reminders, dynamic discount coupons, and real-time cart analytics for OpenCart 3.x and 4.x.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Abandoned Cart Recovery Pro</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '39.0000', 'catalog/marketplace/ext_49866.jpg', 'catalog/marketplace/ext_49866.jpg', 'opencart,extension,marketplace', '1', '1', '1', '1', '1', '1', '85', '120', '0', '0', '1', '1', '1', '2026-09-20 10:00:00', '2026-08-23 10:00:00'),
('49855', '1', '23', 'Social Share Pro for OpenCart', '<p>Social Share Pro for OpenCart: Bring more visitors to every product in your OpenCart 4 store: share buttons that reward customers for sharing, free product listings on Google, Facebook, Instagram, TikTok and Pinterest.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Social Share Pro for OpenCart</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '99.0000', 'catalog/marketplace/ext_49855.jpg', 'catalog/marketplace/ext_49855.jpg', 'opencart,extension,marketplace', '1', '1', '1', '1', '1', '1', '64', '95', '0', '0', '1', '1', '1', '2026-09-18 10:00:00', '2026-10-11 10:00:00'),
('49848', '1', '24', 'SEO Pro for OpenCart', '<p>SEO Pro for OpenCart: Everything your OpenCart 4 store needs to rank: clean SEO URLs for every store and language, meta tag templates, Google rich results, social sharing tags, XML sitemaps, robots.txt, 301 redirects, a 404 log and an SEO audit.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>SEO Pro for OpenCart</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '99.0000', 'catalog/marketplace/ext_49848.jpg', 'catalog/marketplace/ext_49848.jpg', 'opencart,extension,marketplace', '1', '1', '1', '1', '1', '1', '112', '160', '0', '0', '1', '1', '1', '2026-09-15 10:00:00', '2026-10-10 10:00:00'),
('49841', '2', '5', 'Multi-Store Product Separation', '<p>Multi-Store Product Separation: Run truly separate stores from one OpenCart 4 installation: each store gets its own product range, prices, specials, stock, product wording and images, and each store manager sees only their own store\'s products.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Multi-Store Product Separation</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '39.0000', 'catalog/marketplace/ext_49841.jpg', 'catalog/marketplace/ext_49841.jpg', 'opencart,extension,marketplace', '1', '1', '1', '1', '1', '1', '72', '105', '0', '0', '1', '1', '1', '2026-09-12 10:00:00', '2026-10-09 10:00:00'),
('49825', '1', '5', 'POS Pro', '<p>POS Pro for OpenCart: Sell in your shop, at a market stall or at an event from the same OpenCart 4 store you run online. A fast, touch-friendly till that runs in any browser on a PC or tablet, with receipts, cashiers with PINs, shifts and Z reports.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>POS Pro</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '99.0000', 'catalog/marketplace/ext_49825.jpg', 'catalog/marketplace/ext_49825.jpg', 'opencart,extension,marketplace', '1', '1', '1', '1', '1', '1', '94', '140', '0', '0', '1', '1', '1', '2026-09-10 10:00:00', '2026-10-08 10:00:00'),
('49802', '2', '5', 'Warehouse Management System', '<p>WAREHOUSE MANAGEMENT SYSTEM: Run multiple warehouses from your OpenCart 4 admin: stock per location, bin locations, transfers, purchase orders, goods receiving, pick lists and packing slips, while your storefront stock stays exactly right.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Warehouse Management System</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '99.0000', 'catalog/marketplace/ext_49802.jpg', 'catalog/marketplace/ext_49802.jpg', 'opencart,extension,marketplace', '1', '1', '1', '1', '1', '1', '88', '130', '0', '0', '1', '1', '1', '2026-09-08 10:00:00', '2026-10-07 10:00:00'),
('49796', '1', '7', 'Sales Reports Pro', '<p>Sales Reports Pro - Accounting Exports: Professional sales, tax, product, customer and refund reports for OpenCart 4, with one-click CSV, Excel and PDF exports for your accountant.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Sales Reports Pro</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '99.0000', 'catalog/marketplace/ext_49796.jpg', 'catalog/marketplace/ext_49796.jpg', 'opencart,extension,marketplace', '1', '1', '1', '1', '1', '1', '118', '175', '0', '0', '1', '1', '1', '2026-09-05 10:00:00', '2026-10-06 10:00:00'),
('49295', '1', '20', 'InventorySync: one click to list and sell on more channels', '<p>InventorySync REST API: Selling in more than one place is what breaks your stock counts. Synchronize your OpenCart inventory across Amazon, eBay, Etsy, and POS in real time.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>InventorySync: one click to list and sell on more channels</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '0', '12', '0.0000', 'catalog/marketplace/ext_49295.jpg', 'catalog/marketplace/ext_49295.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '0', '1420', '0', '0', '1', '1', '1', '2026-08-25 10:00:00', '2026-10-05 10:00:00'),
('31346', '2', '19', 'Universal Data Feed (Google Merchant, Bing shopping, Facebook)', '<p>Universal Data Feed creates any type of feed using custom feeds, allowing you to choose exactly what you want to display. Unlimited size, tested with 100K+ products, intelligent cache and on-the-fly generation.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Universal Data Feed (Google Merchant, Bing shopping, Facebook)</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '69.0000', 'catalog/marketplace/ext_31346.jpg', 'catalog/marketplace/ext_31346.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '920', '1450', '5', '35', '1', '1', '1', '2024-04-10 10:00:00', '2026-10-04 10:00:00'),
('48431', '1', '22', 'EcomAiBridge OpenCart V4', '<p>Make your Store visible to AI. EcomAiBridge connects your OpenCart store to an AI Chat Widget, MCP server, and JSON REST API. Make your products visible to ChatGPT, Claude, Gemini and every AI app in minutes.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>EcomAiBridge OpenCart V4</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '0', '12', '0.0000', 'catalog/marketplace/ext_48431.jpg', 'catalog/marketplace/ext_48431.jpg', 'opencart,extension,marketplace', '1', '0', '0', '1', '1', '1', '0', '2350', '5', '1', '1', '1', '1', '2026-08-01 10:00:00', '2026-10-03 10:00:00'),
('48430', '1', '22', 'EcomAiBridge OpenCart V3', '<p>Make your Store visible to AI. EcomAiBridge connects your OpenCart 3 store to an AI Chat Widget, MCP server, and JSON REST API. Make your products visible to ChatGPT, Claude, Gemini and every AI app in minutes.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>EcomAiBridge OpenCart V3</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '0', '12', '0.0000', 'catalog/marketplace/ext_48430.jpg', 'catalog/marketplace/ext_48430.jpg', 'opencart,extension,marketplace', '1', '0', '0', '1', '1', '1', '0', '1890', '0', '0', '1', '1', '1', '2026-08-01 10:00:00', '2026-10-02 10:00:00'),
('45380', '2', '1', 'Ronixa Theme - OpenCart Live Drag and Drop Page Builder', '<p>RONIXA Theme is more than just an OpenCart theme. It uses Retrina Live Drag & Drop Page Builder that enables you to more quickly build incredible websites.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Ronixa Theme - OpenCart Live Drag and Drop Page Builder</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '69.0000', 'catalog/marketplace/ext_45380.jpg', 'catalog/marketplace/ext_45380.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '780', '1120', '5', '32', '1', '1', '1', '2024-09-10 10:00:00', '2026-10-01 10:00:00'),
('21842', '1', '5', 'Pro Email Template', '<p>Customize the content and design of each email model according to your convenience: great responsive templates included, customize text and subject, define your color scheme, instant preview result, multi-store support.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Pro Email Template</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '49.0000', 'catalog/marketplace/ext_21842.jpg', 'catalog/marketplace/ext_21842.jpg', 'opencart,extension,marketplace', '1', '0', '0', '1', '1', '1', '1640', '2450', '5', '58', '1', '1', '1', '2023-03-14 10:00:00', '2026-09-28 10:00:00'),
('15075', '1', '6', 'PDF Invoice Pro', '<p>PDF Invoice will be automatically generated and sent upon order confirmation or on specific order status. The customer can also download in his user account, and the admin orders section. Customize finely the invoice to match your brand.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>PDF Invoice Pro</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '59.0000', 'catalog/marketplace/ext_15075.jpg', 'catalog/marketplace/ext_15075.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '2890', '4100', '5', '94', '1', '1', '1', '2023-02-10 10:00:00', '2026-09-25 10:00:00'),
('27350', '2', '8', 'Universal Import/Export Pro', '<p>This module allows you to import or export easily lists (products, categories, customers, orders) from CSV, XML, XLS, XLSX, JSON, TXT, TSV, or ODS files. Unlimited file size and cron automation included.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Universal Import/Export Pro</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '99.0000', 'catalog/marketplace/ext_27350.jpg', 'catalog/marketplace/ext_27350.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '1950', '3100', '5', '61', '1', '1', '1', '2023-05-22 10:00:00', '2026-09-22 10:00:00'),
('35669', '1', '19', 'Google Shopping for OpenCart', '<p>Meet Google Shopping for OpenCart! Your marketing tool allowing effortless promotion for products from your OpenCart store to shoppers who are searching for them online on Google Merchant Center.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Google Shopping for OpenCart</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '0', '12', '0.0000', 'catalog/marketplace/ext_35669.jpg', 'catalog/marketplace/ext_35669.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '0', '19400', '3', '16', '1', '1', '1', '2023-07-19 10:00:00', '2026-09-20 10:00:00'),
('9486', '1', '24', 'Complete SEO Package - the best seo extension for OpenCart', '<p>Everything for SEO in one module: easy to use, intuitive and beautiful ergonomic interface. All settings are managed from one place! Manage easily all your OpenCart SEO and improve your Google ranking.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Complete SEO Package - the best seo extension for OpenCart</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '99.0000', 'catalog/marketplace/ext_9486.jpg', 'catalog/marketplace/ext_9486.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '4320', '6200', '5', '127', '1', '1', '1', '2023-01-15 10:00:00', '2026-09-18 10:00:00'),
('31461', '2', '20', 'Purpletree Multivendor MultiSeller | Supplier Marketplace', '<p>All-Time Best-Selling Multi-Vendor Marketplace Extension on OpenCart.com – Powering Successful Online Marketplaces Worldwide. Turn your OpenCart store into a complete multi-seller marketplace.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Purpletree Multivendor MultiSeller | Supplier Marketplace</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '39.9900', 'catalog/marketplace/ext_31461.jpg', 'catalog/marketplace/ext_31461.jpg', 'opencart,extension,marketplace', '1', '0', '0', '1', '1', '1', '2150', '3400', '4', '88', '1', '1', '1', '2023-08-14 10:00:00', '2026-09-15 10:00:00'),
('47912', '2', '21', 'OpenCart Zapier, Make.com Custom Webhooks (Automation)', '<p>OpenCart Webhooks for Zapier & Make.com - Complete Automation Solution. Automate your OpenCart store with Zapier, Make.com, and 7,000+ apps! Send real-time webhooks for orders, customers, products, and reviews.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>OpenCart Zapier, Make.com Custom Webhooks (Automation)</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '59.0000', 'catalog/marketplace/ext_47912.jpg', 'catalog/marketplace/ext_47912.jpg', 'opencart,extension,marketplace', '1', '0', '0', '1', '1', '1', '135', '210', '0', '0', '1', '1', '1', '2025-11-10 10:00:00', '2026-09-12 10:00:00'),
('48259', '2', '4', 'Multiple Flat Rate – 10 Shipping Options', '<p>Give customers more shipping choices with 10 configurable flat rates — including order total based shipping, geo-zone filtering, and tax class support.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Multiple Flat Rate – 10 Shipping Options</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '20.0000', 'catalog/marketplace/ext_48259.jpg', 'catalog/marketplace/ext_48259.jpg', 'opencart,extension,marketplace', '1', '0', '0', '1', '1', '1', '92', '145', '0', '0', '1', '1', '1', '2026-01-20 10:00:00', '2026-09-10 10:00:00'),
('31030', '1', '20', 'OpenCart Android IOS App', '<p>OpenCart Android & iOS Mobile App: Take your OpenCart store mobile and reach customers on the go! The OpenCart Mobile App for Android and iOS offers a fast, seamless, and fully synchronized shopping experience.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>OpenCart Android IOS App</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '399.0000', 'catalog/marketplace/ext_31030.jpg', 'catalog/marketplace/ext_31030.jpg', 'opencart,extension,marketplace', '1', '0', '0', '1', '1', '1', '180', '260', '5', '1', '1', '1', '1', '2024-03-18 10:00:00', '2026-09-08 10:00:00'),
('48580', '1', '22', 'AI Product Recommendation Engine', '<p>AI Product Recommendation Engine is a smart module for OpenCart that automatically generates related product recommendations using AI logic. It helps store owners increase sales, cross-selling, and customer engagement.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>AI Product Recommendation Engine</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '99.0000', 'catalog/marketplace/ext_48580.jpg', 'catalog/marketplace/ext_48580.jpg', 'opencart,extension,marketplace', '1', '0', '0', '1', '1', '1', '76', '110', '0', '0', '1', '1', '1', '2026-04-12 10:00:00', '2026-09-05 10:00:00'),
('29703', '1', '5', 'OpenCart Point of Sale System POS', '<p>OpenCart Point of Sale System allows you to keep track of sales and inventory with a physical system on the store and an application to manage your invoicing, billing & inventory.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>OpenCart Point of Sale System POS</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '99.0000', 'catalog/marketplace/ext_29703.jpg', 'catalog/marketplace/ext_29703.jpg', 'opencart,extension,marketplace', '1', '0', '0', '1', '1', '1', '640', '980', '5', '21', '1', '1', '1', '2023-10-05 10:00:00', '2026-09-03 10:00:00'),
('46854', '2', '7', 'Google Analytics & Facebook Pixel Event', '<p>OpenCart Google Analytics & Facebook Pixel Event module is designed to help businesses effectively track, analyze and optimize user behavior on their websites with GA4 and Meta Pixel events.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>Google Analytics &amp; Facebook Pixel Event</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '29.9900', 'catalog/marketplace/ext_46854.jpg', 'catalog/marketplace/ext_46854.jpg', 'opencart,extension,marketplace', '1', '0', '0', '1', '1', '1', '145', '230', '0', '0', '1', '1', '1', '2025-05-14 10:00:00', '2026-09-02 10:00:00'),
('42770', '1', '2', 'RocketBoost', '<p>This extension improves your website speed by working on different optimization fields, one of the most powerful being the smart caching system which saves generated pages for instant display.</p>', '<h4>Installation & Configuration</h4><ol><li>Upload the extension package via <strong>Extensions &gt; Installer</strong> in your OpenCart Admin.</li><li>Navigate to <strong>Extensions &gt; Extensions</strong> and enable <strong>RocketBoost</strong>.</li><li>Configure your settings and save.</li></ol>', 'Updated for OpenCart 4.1.0.4 and 3.0.5.1 compatibility.', '1', '12', '70.0000', 'catalog/marketplace/ext_42770.jpg', 'catalog/marketplace/ext_42770.jpg', 'opencart,extension,marketplace', '1', '1', '0', '1', '1', '1', '410', '620', '5', '3', '1', '1', '1', '2024-07-01 10:00:00', '2026-09-01 10:00:00');
