INSERT INTO `oc_extension_comment` (`extension_comment_id`, `extension_id`, `parent_id`, `member_id`, `comment`, `status`, `date_added`) VALUES
('1', '38358', '0', '4', 'Works out of the box with OpenCart 3.0.5.1 and 4.1.0.4! Smart buttons and Pay Later messaging boosted our checkout conversion.', '1', '2026-01-22 14:10:00'),
('2', '38358', '1', '1', 'Thank you for your feedback! Let us know if you need any assistance with 3D Secure configuration.', '1', '2026-01-22 16:05:00'),
('3', '49848', '0', '4', 'Does SEO Pro for OpenCart support multi-language SEO URLs for OpenCart 4.1?', '1', '2026-02-02 09:30:00'),
('4', '49848', '3', '1', 'Yes! Full multi-language SEO URLs and automatic hreflang tags are included.', '1', '2026-02-02 10:15:00');
