INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES
('1', '1', 'Extension Developer Policy', '<div class=\"container\"><h3>OpenCart Extension Developer Policy</h3><p>All extensions uploaded to the OpenCart Marketplace must adhere to OpenCart coding standards, include documentation, and remain free of malicious or obfuscated code.</p></div>', 'Extension Developer Policy', 'OpenCart Extension Developer Policy', 'opencart, developer, policy'),
('2', '1', 'Extension Developer', '<div class=\"container\">    <h2 class=\"text-center\">How to register a seller account on OpenCart?</h2><br><br>    <div class=\"row\">      <div class=\"col-md-10 col-md-offset-1\">        <div class=\"row\">          <div class=\"col-sm-7\">            <h3>Step 1. Create an OpenCart account</h3>            <p>By registering an OpenCart account you will be able to get access to downloading among our free modules, uploading your OpenCart site to our Showcase selection and getting exposure and becoming an OpenCart partner</p>            <p>Go to OpenCart website and click on the register button. Fill in your username, email address, first name, last name, country and set your password.</p>          </div>          <div class=\"col-sm-5\">            <p><a href=\"index.php?route=account/register\"> <img src=\"image/original/5912e82f3d215.jpg\" alt=\"OpenCart - Create an OpenCart Account\" title=\"OpenCart - Create an OpenCart Account\" class=\"img-responsive thumbnail\" style=\"margin-left:auto; margin-right:auto;\"></a>            </p>                     </div>        </div>        <hr>        <div class=\"row\">          <div class=\"col-sm-7\">            <h3>Step 2. Apply to become a seller</h3>            <p>After you login to your OpenCart account, please scroll down, to the Extensions section and click Apply to become a seller.</p>          </div>          <div class=\"col-sm-5\">            <p><img src=\"image/original/59141001f0033.jpg\" alt=\"OpenCart - Apply to become a seller\" title=\"OpenCart - Apply to become a seller\" class=\"img-responsive thumbnail\" style=\"margin-left:auto; margin-right:auto;\"></p>          </div>        </div>        <hr>        <div class=\"row\">          <div class=\"col-sm-7\">            <h3>Step 3. Filling in your details</h3>            <p>Please fill in the form information details in cluding your email address, first and last name, country, phone number and set up your payout information.<br>Approvals normally take up to 48 hours.</p>          </div>          <div class=\"col-sm-5\">            <p><img src=\"image/original/5912e911c8d71.jpg\" alt=\"OpenCart - My Seller account\" title=\"OpenCart - My Seller account\" class=\"img-responsive thumbnail\" style=\"margin-left:auto; margin-right:auto;\"></p>          </div>        </div>        </div>    </div>      </div><div class=\"container-fluid\">  <div class=\"container\">    <h3 class=\"text-center\">Payment method</h3>    <p class=\"text-center\">OpenCart offers the following two payment gateway options to payout sellers.<br>Paypal&nbsp;paid out within 7days &nbsp;of every following month. Payoneer paid out within 10days &nbsp;of every following month.</p><p class=\"text-center\"><br></p>        <div class=\"row\">      <div class=\"col-md-8 col-md-offset-2\">        <div class=\"row\">          <div class=\"col-xs-6\">            <a href=\"https://www.paypal.com/uk/\" target=\"_blank\"> <img src=\"image/original/5912bf295a699.jpg\" alt=\"PayPal\" title=\"PayPal\" class=\"img-responsive thumbnail\"> </a>          </div>          <div class=\"col-xs-6\">            <a href=\"https://www.payoneer.com/\" target=\"_blank\"> <img src=\"image/original/5912be5d58d32.jpg\" alt=\"Payonner\" title=\"Payonner\" class=\"img-responsive thumbnail\"> </a>          </div>        </div>      </div>    </div>      </div></div><div class=\"container\">    <h3 class=\"text-center\">Our Sales commission rates</h3>        <div class=\"row\">      <div class=\"col-md-8 col-md-offset-2\">        <h4 class=\"text-center\">$700 monthly</h4>        <div class=\"progress\">          <div class=\"progress-bar progress-bar-danger\" role=\"progressbar\" aria-valuenow=\"50\" aria-valuemin=\"0\" aria-valuemax=\"100\" style=\"width:50%\">50% Commission rate <span class=\"sr-only\">50%</span>          </div>        </div>        <h4 class=\"text-center\">Between $701 - $849 monthly</h4>        <div class=\"progress\">          <div class=\"progress-bar progress-bar-warning\" role=\"progressbar\" aria-valuenow=\"40\" aria-valuemin=\"0\" aria-valuemax=\"100\" style=\"width:40%\">40% Commission rate <span class=\"sr-only\">40%</span>          </div>        </div>        <h4 class=\"text-center\">Between $850 - $999 monthly</h4>        <div class=\"progress\">          <div class=\"progress-bar progress-bar-success\" role=\"progressbar\" aria-valuenow=\"30\" aria-valuemin=\"0\" aria-valuemax=\"100\" style=\"width:30%\">30% Commission rate <span class=\"sr-only\">30%</span>          </div>        </div>        <h4 class=\"text-center\">Above $1,000 monthly</h4>        <div class=\"progress\">          <div class=\"progress-bar progress-bar-info\" role=\"progressbar\" aria-valuenow=\"25\" aria-valuemin=\"0\" aria-valuemax=\"100\" style=\"width:25%\">25% Commission rate <span class=\"sr-only\">25% Complete</span>          </div></div>              </div></div>\n<p class=\"text-center\">The commission rate will decrease depends on the last 6 months of the monthly sales.</p>\n</div>\n<div class=\"container-fluid\">\n  <div class=\"container\">\n      <h3 class=\"text-center\">Cloud Developer</h3>\n      <br>\n      <div class=\"row\">\n        <div class=\"col-sm-6\"><img src=\"application/view/image/feature/developer/marketplace.png\" alt=\"Marketplace for third-party extensions\" title=\"Marketplace for third-party extensions\" class=\"img-responsive\"></div>\n        <div class=\"col-sm-6\">\n          <br>\n          <br>\n          <h4 style=\"font-weight:bold; color: #000;\">Requirement for the Cloud Marketplace:</h4>\n          <ol style=\"margin-left: -20px;\">\n            <li>Only support OpenCart version 3.0 or above.</li>\n            <li>The folder name must be named \"upload\" / The file name must be \"install.xml\"</li>\n            <li>The compression should be in Zip format.</li>\n          </ol>\n        </div>\n      </div>\n  </div>\n</div>', 'How to be a seller of Opencart?', 'How to become an Opencart Seller', 'seller, opencart, how to become an opencart seller, opencart seller, ');
