INSERT INTO `oc_member_partner` (`member_partner_id`, `member_id`, `member_partner_type_id`, `member_partner_status_id`, `firstname`, `lastname`, `company`, `website`, `email`, `telephone`, `description_short`, `description_long`, `address_1`, `address_2`, `city`, `postcode`, `country_id`, `zone_id`, `image`, `facebook`, `twitter`, `linkedin`, `status`, `date_added`, `date_modified`) VALUES
('1', '1', '2', '1', 'Vlad', 'Georgiev', 'ScalaHosting', 'https://www.scalahosting.com/opencart-hosting.html', 'sales@scalahosting.com', '+1 866 894 9346', 'OpenCart partners exclusively with ScalaHosting for two key reasons: exceptional eCommerce speed and performance, and the most reliable 24/7 human support weÔÇÖve experienced in the hosting industry.', 'OpenCart partners exclusively with ScalaHosting for two key reasons: exceptional eCommerce speed and performance, and the most reliable 24/7 human support weÔÇÖve experienced in the hosting industry.<br /><br />ScalaHosting provides managed cloud VPS hosting optimized specifically for OpenCart 3 and OpenCart 4 stores, featuring SShield cybersecurity, daily remote backups, and free effortless migration.', '1999 Bryan St, Suite 900', '', 'Dallas', '75201', '223', '3669', 'partner/scalahosting.jpg', 'https://www.facebook.com/scalahosting', 'https://twitter.com/scalahosting', 'https://www.linkedin.com/company/scalahosting', '1', '2021-06-15 09:00:00', '2026-01-10 09:00:00'),
('2', '2', '1', '1', 'Nicolas', 'R', 'GeekoDev', 'https://geekodev.com', 'support@geekodev.com', '+353899418576', 'Expert opencart extension developer since 2010, geekodev is providing best selling and highest quality extensions.', 'GeekoDev is developing opencart extensions since 2010.<br /><br />We have great experience of opencart, making some of most popular extensions.<br /><br />We focus on making modules of high quality, great ergonomic, best performance, and taking care of not breaking compatibility with 3rd party modules, and quick reliable support.<br /><br />You can contact us if you need specific extension development or custom work for opencart!', '77 Camden Street Lower', '', 'Dublin', 'D02XE80', '103', '1528', 'partner/geekodev.jpg', '', '', '', '1', '2011-05-10 12:00:00', '2026-01-10 09:00:00'),
('3', '4', '1', '1', 'Paul', 'Feakins', 'Antropy', 'https://www.antropy.co.uk/', 'info@antropy.co.uk', '+44208 123 1273', 'The UK\'s best OpenCart Partner - for a quick estimate on your task contact us today - info@antropy.co.uk', 'Antropy has a friendly team of talented industry professionals who specialize in designing, building, hosting and supporting incredibly successful OpenCart ecommerce websites for companies ranging from startups to blue chips. <br /><br />Managing Director, Paul Feakins spent many years in the industry as a Senior Web Developer and Consultant before founding the company and gathering some of the most talented web professionals around him. <br /><br />Technical experience makes Antropy unafraid of complex development work that many design-lead agencies would shy away from and a D&amp;AD award show their design work is on-point too.<br /><br />The name &quot;Antropy&quot; means simplicity. When code is simple and clean, it\'s also fast and flexible. When design is simple and clean, customers can easily convert.<br /><br />Get in touch to discuss your project today: <a href=\"mailto:info@antropy.co.uk\" rel=\"nofollow\">info@antropy.co.uk</a>', 'Antropy Consulting Limited', 'Crawley Business Centre', 'Crawley', 'RH10 1TN', '222', '3608', 'partner/antropy.jpg', 'https://www.facebook.com/Antropy.co.uk', 'https://twitter.com/AntropyWebsites', 'https://www.linkedin.com/company/antropy-consulting', '1', '2011-08-20 10:00:00', '2026-01-10 09:00:00'),
('4', '3', '1', '2', 'Dimitri', 'K', 'Dreamvention O├£', 'https://dreamvention.ee/', 'hello@dreamvention.com', '+380987209119', 'Selling online is a difficult task. Not only you have to develop and launch an outstanding e-commerce site, but you also have to implement analytics, set up funnels and constantly advertise and promote your site online. Not to mention taking care or the assortment and managing inventory. Well, we can help you do the IT part right :) www.dreamvention.com', 'Since 2010 we have helped over 270 OpenCart customers set up their OpenCart Stores. Our Extensions are used by over 60K users worldwide every day. Ajax Quick Checkout, Visual Designer, Social Login, Seo Module, Carbon, Filter are the number one OpenCart Extensions with outstanding coding. <br /><br />We set up OpenCart Stores, Analytics and Sales funnels, Provided OpenCart SEO and Advertising and helped customers implement lead nurturing. <br /><br />If you are searching for OpenCart Experts, that have the know-how to develop OpenCart stores the proper way, we are your top pick. We offer outstanding OpenCart Support on the market and we are happy to help you succeed.', 'Liikuri 10-107', '', 'Tallinn', '13618', '67', '1054', 'partner/dreamvention.jpg', 'https://www.facebook.com/dreamvention/', 'https://twitter.com/dreamvention', 'https://www.linkedin.com/company/dreamvention', '1', '2012-01-15 10:00:00', '2026-01-10 09:00:00'),
('5', '1', '1', '3', 'Coding', 'Inspect', 'Codinginspect', 'https://codinginspect.com', 'codinginspect@gmail.com', '+91 9876543210', 'Founded in 2017, Codinginspect has been developing exceptional modules for e-commerce websites since 2014, specializing in Opencart framework. With 12+ years of programming experience, we are dedicated to providing top-notch development and support services to help businesses succeed in the e-commerce space. Contact us at codinginspect@gmail.com', 'Founded in 2017, Codinginspect has been developing exceptional modules for e-commerce websites since 2014, specializing in Opencart framework. With 12+ years of programming experience, we are dedicated to providing top-notch development and support services to help businesses succeed in the e-commerce space.', 'Sector 62', '', 'Noida', '201309', '99', '1505', 'partner/codinginspect.jpg', '', '', '', '1', '2017-04-12 09:00:00', '2026-01-10 09:00:00'),
('6', '2', '1', '1', 'TMD', 'Software', 'TMD Software Private Limited', 'https://www.opencartextensions.in/', 'support@tmdextensions.com', '+91 161 5027595', 'We at TMD Software Pvt. Ltd have crafted 300+ Modules, Applications and Themes in OpenCart so far. With 12+ years of hands-on experience, our skilled team of web developers and engineers specializes in delivering custom OpenCart development solutions tailored to meet the unique needs of both small and large-scale businesses.', 'We at TMD Software Pvt. Ltd have crafted 300+ Modules, Applications and Themes in OpenCart so far. With 12+ years of hands-on experience, our skilled team of web developers and engineers specializes in delivering custom OpenCart development solutions tailored to meet the unique needs of both small and large-scale businesses.', 'SCO 30, 2nd Floor', 'Feroze Gandhi Market', 'Ludhiana', '141001', '99', '1500', 'partner/tmd.jpg', 'https://www.facebook.com/opencartextensions.in', 'https://twitter.com/tmdsoftware', 'https://www.linkedin.com/company/tmd-software-pvt-ltd', '1', '2014-03-18 11:00:00', '2026-01-10 09:00:00'),
('7', '1', '3', '2', 'PayPal', 'Partner', 'PayPal', 'https://www.paypal.com', 'partners@paypal.com', '+353 1 436 9000', 'PayPal has remained at the forefront of the digital payment revolution for more than 20 years. By leveraging technology to make financial services and commerce more convenient, affordable, and secure, the PayPal platform is empowering more than 429 million consumers and merchants in more than 200 markets to join and thrive in the global economy.', 'PayPal has remained at the forefront of the digital payment revolution for more than 20 years. By leveraging technology to make financial services and commerce more convenient, affordable, and secure, the PayPal platform is empowering more than 429 million consumers and merchants in more than 200 markets to join and thrive in the global economy.', 'Ballycoolin Business Park', 'Blanchardstown', 'Dublin', 'D15', '103', '1528', 'partner/paypal.jpg', 'https://www.facebook.com/PayPal', 'https://twitter.com/PayPal', 'https://www.linkedin.com/company/paypal', '1', '2015-01-10 09:00:00', '2026-01-10 09:00:00'),
('8', '3', '1', '3', 'Jan', 'De Vries', 'OpenCart Specialist', 'https://www.opencartspecialist.nl', 'info@opencartspecialist.nl', '+31 20 123 4567', 'Join countless other businesses who experience more sales, better customer retention and increased freedom with their fully customized OpenCart store. We make your store run smoother, faster and more efficiently than you could ever imagine.', 'Join countless other businesses who experience more sales, better customer retention and increased freedom with their fully customized OpenCart store. We make your store run smoother, faster and more efficiently than you could ever imagine.', 'Herengracht 182', '', 'Amsterdam', '1016 BR', '150', '2328', 'partner/opencartspecialist.jpg', '', '', '', '1', '2016-09-05 14:00:00', '2026-01-10 09:00:00');
